    /// The sizes the export sheet offers for `preset_id` against this
    /// document, as the JSON array of `{id, name, width, height}` rows
    /// `rc_export_sizes` returns, in menu order — the first is the default.
    ///
    /// The rows:
    ///
    /// 1. `preset` — the format's cap, "GIF default" / "APNG default", for
    ///    the two rows of the table that carry one; nothing for the rest.
    /// 2. `document` — "Document size", the canvas as it is; on a row that
    ///    needs even dimensions the canvas evened ([`even_size`]), named
    ///    "Document (even)" when that is not the canvas's own size.
    /// 3. `2160p` ("4K"), `1440p`, `1080p`, `720p` — the short edge named,
    ///    the long edge fitted to the canvas and rounded to even.
    ///
    /// On an image format every row's numbers are the canvas fitted inside
    /// that row's box, never upscaled — the size the file will have. Rows
    /// may repeat an earlier row's numbers and are listed anyway (the
    /// module doc says why); the sheet hides the repeats.
    ///
    /// One list for every movie format, the audio-only row included: a
    /// width is reported for it the way `export_settings` reports one, and
    /// the sheet disables the control rather than this module keeping a
    /// second rule for one row. `Err` for an unknown preset, naming it —
    /// the same lookup and the same words as `export_settings`.
    pub fn export_sizes(&self, preset_id: &str) -> Result<Value, String> {
        let preset = export::preset(preset_id)?;
        let document = (self.canvas.width, self.canvas.height);
        let fits = preset.fits_inside_size();
        let sized = |(width, height): (u32, u32)| {
            if fits {
                fit_within(document, (width, height))
            } else {
                (width, height)
            }
        };

        let mut rows: Vec<Row> = Vec::new();
        if let Some(cap) = preset.size {
            // The codec in capitals is the format's name as people write
            // it — GIF, APNG — for the two rows that carry a cap.
            let (width, height) = sized(cap);
            rows.push(Row {
                id: "preset",
                name: format!("{} default", preset.codec.to_uppercase()),
                width,
                height,
            });
        }
        // The id is `document` either way: the name is the popup's, and it
        // changes only when the numbers are not the canvas's.
        let listed = if preset.even_sized() {
            even_size(document)
        } else {
            document
        };
        let name = if listed == document {
            "Document size"
        } else {
            "Document (even)"
        };
        rows.push(Row {
            id: "document",
            name: name.to_string(),
            width: listed.0,
            height: listed.1,
        });
        for (id, name, short) in STANDARD {
            let (width, height) = sized(fitted(document, short));
            rows.push(Row {
                id,
                name: name.to_string(),
                width,
                height,
            });
        }

        Ok(Value::Array(rows.iter().map(Row::to_json).collect()))
    }
}

/// The size whose short edge is `short`, in the aspect of a `width` ×
/// `height` document: the long edge is `short` × the document's long edge
/// over its short one, rounded to the nearest even integer with a tie
/// going up, on the axis the document is longer along. A square document
/// gives `short` × `short`.
fn fitted((width, height): (u32, u32), short: u32) -> (u32, u32) {
        video: true,
        alpha: false,
        // 480 × 270 at 12.5 fps, and both numbers are the point of the
        // preset rather than an afterthought. GIF stores every frame as a
        // whole picture over a 256-colour palette with no inter-frame
        // prediction, so its size is frames × pixels and nothing else:
        // the same ten seconds carries sixteen times the pixels at 1080p
        // and a hundred and thirty at 4K, which is why a full-rate 4K GIF
        // is a file no one can send. At 480 × 270 a ten-second clip lands
        // in single-digit megabytes, and 270 keeps the 16:9 shape the
        // other fixed-size rows use.
        //
        // 12.5 fps is not a rounding of 12. A GIF frame delay is stored in
        // hundredths of a second, so only rates that divide 100 exactly
        // survive the write, and 12.5 (8 cs) is the lowest of those that
        // still reads as motion when a cursor crosses a screen recording.
        // 10 fps (10 cs) visibly steps; 15 fps would want 6.67 cs, which
        // viewers round to 7 and then play at 14.3.
        size: Some((480, 270)),
        fps: Some(Fps { num: 25, den: 2 }),
        avf_preset: None,
        writer: None,
    },
    Preset {
        id: "apng",
        name: "Animated PNG",
        container: Container::Apng,
        codec: "apng",
        video: true,
        // One of the four rows that keep a transparent canvas
        // transparent, and the only one that is not a movie — a lossless
        // frame sequence any browser shows, with no sound.
        alpha: true,
        // 960 × 540 at 25 fps. APNG is true colour and lossless, so it
        // costs more per pixel than GIF but has no palette to quantise to:
        // twice the linear size buys back the detail GIF spends on its 256
        // colours, and the format is worth choosing only for that.
        // The rate is free of GIF's constraint — an `fcTL` delay is an
        // exact rational, not a centisecond count — so it is a familiar 25
        // rather than an arithmetic one; that is half the 50 or 60 a screen
        // recording arrives at and smooth enough that the cap is invisible.
        size: Some((960, 540)),
        fps: Some(Fps { num: 25, den: 1 }),
        avf_preset: None,
        writer: None,
    },
];

